<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TrustedClient\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Retrieve\TrustedClientRetrieveUsecase;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Features\Access\TrustedClient\Application\Usecase\Retrieve\TrustedClientRetrieveResult;

class TrustedClientRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TrustedClientRetrieveUsecase $retrieveUsecase,
        private readonly AesCypherService $cypherService,
    ) {
    }
    #[OA\Get(
        path: "/api/access/trusted-clients{uid}",
        tags: ["Trusted client"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/TrustedClientApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve Trusted client");
        $span = $this->startSpan("Retrieve Trusted client");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapTrustedClient($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapTrustedClient(ServerRequestInterface $request, TrustedClientRetrieveResult $value): TrustedClientApiDTO
    {
        $this->logDebug("Map entity to output dto for Trusted client");
        $span = $this->startSpan("Map entity to output dto for Trusted client");
        try {
            $dto = new TrustedClientApiDTO();
            $dto->uid = $value->getUid();
            $dto->code = $value->getCode();
            $dto->allowAllScopes = $value->isAllowAllScopes();
            $dto->publicAllow = $value->isPublicAllow();
            $allowedRedirects = [];
            $existentsAllowedRedirects = $value->getAllowedRedirects();
            if (null !== $existentsAllowedRedirects) {
                foreach ($allowedRedirects as $item) {
                    $allowedRedirects[] = [
                    'uid' => $item->uid(),
                    'url' => $item->getUrl(),
                    'version' => $item->getVersion(),
                    ];
                }
            }
            $dto->allowedRedirects = $allowedRedirects;
            $dto->secretOauth = '******';
            $dto->backChannelLogoutUri = $value->getBackChannelLogoutUri();
            $dto->backChannelLogoutSessionRequired = $value->isBackChannelLogoutSessionRequired();
            $dto->frontChannelLogoutUri = $value->getFrontChannelLogoutUri();
            $dto->frontChannelLogoutSessionRequired = $value->isFrontChannelLogoutSessionRequired();
            $dto->enabled = $value->isEnabled();
            $dto->registrationAccess = $value->getRegistrationAccess();
            $dto->clientName = $value->getClientName();
            $dto->logoUri = $value->getLogoUri();
            $dto->clientUri = $value->getClientUri();
            $dto->policyUri = $value->getPolicyUri();
            $dto->tosUri = $value->getTosUri();
            $dto->tokenEndpointAuthMethod = $value->getTokenEndpointAuthMethod();
            $dto->grantTypesJson = $value->getGrantTypesJson();
            $dto->responseTypesJson = $value->getResponseTypesJson();
            $dto->dynamicallyRegistered = $value->isDynamicallyRegistered();
            $dto->registeredAt = $value->getRegisteredAt()?->format(DateTime::ATOM);
            $dto->allowedScopesM2m = $value->getAllowedScopesM2m();
            $dto->m2mTokenTtlSeconds = $value->getM2mTokenTtlSeconds();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
